/**
 * A Lexical Preserving Printer is used to capture all the lexical information while parsing, update them when
 * operating on the AST and then use them to reproduce the source code in its original formatting.
 */
public class LexicalPreservingPrinter {
    private static final String JAVA_UTIL_OPTIONAL = Optional.class.getCanonicalName();
    private static final String JAVAPARSER_AST_NODELIST = NodeList.class.getCanonicalName();
    private static AstObserver observer;

    /** The key used to store a node's lexical text. */
    public static final DataKey<NodeText> NODE_TEXT_DATA = new DataKey<NodeText>() {};
    private static final LexicalDifferenceCalculator LEXICAL_DIFFERENCE_CALCULATOR = new LexicalDifferenceCalculator();

    public static <N extends Node> N setup(N node) {
        assertNotNull(node);
        if (observer == null) observer = createObserver();
        node.getTokenRange().ifPresent(r -> {
            storeInitialText(node);
            if (!node.isRegistered(observer)) node.registerForSubtree(observer);
        });
        return node;
    }

    public static boolean isAvailableOn(Node node) {
        return node.containsData(NODE_TEXT_DATA);
    }

    private static AstObserver createObserver() {
        return new Observer();
    }

    private static class Observer extends PropagatingAstObserver {
        @Override
        public void concretePropertyChange(Node observedNode, ObservableProperty property, Object oldValue, Object newValue) {
            if (oldValue == newValue || property == ObservableProperty.RANGE || property == ObservableProperty.COMMENTED_NODE) return;
            if (property == ObservableProperty.COMMENT) {
                Optional<Node> parentNode = observedNode.getParentNode();
                NodeText nodeText = parentNode.map(LexicalPreservingPrinter::getOrCreateNodeText).orElse(getOrCreateNodeText(observedNode));
                if (oldValue == null) {
                    int index = parentNode.isPresent() ? nodeText.findChild(observedNode) : 0;
                    fixIndentOfMovedNode(nodeText, index);
                    LineSeparator separator = observedNode.getLineEndingStyleOrDefault(LineSeparator.SYSTEM);
                    nodeText.addElement(index, makeCommentToken((Comment) newValue));
                    nodeText.addToken(index + 1, eolTokenKind(separator), separator.asRawString());
                } else if (newValue == null) {
                    if (!(oldValue instanceof Comment)) throw new UnsupportedOperationException("Trying to remove something that is not a comment!");
                    if (((Comment) oldValue).isOrphan()) nodeText = getOrCreateNodeText(observedNode);
                    int index = getIndexOfComment((Comment) oldValue, nodeText);
                    nodeText.removeElement(index);
                    if (isCompleteLine(nodeText.getElements(), index)) removeAllExtraCharacters(nodeText.getElements(), index);
                    else removeAllExtraCharactersStartingFrom(nodeText.getElements().listIterator(index));
                } else {
                    List<TokenTextElement> matches = findTokenTextElementForComment((Comment) oldValue, nodeText);
                    if (matches.size() != 1) throw new IllegalStateException("The matching comment to be replaced could not be found");
                    TokenTextElement match = matches.get(0);
                    nodeText.replace(match.and(match.matchByRange()), makeCommentToken((Comment) newValue));
                }
            }
            NodeText nodeText = getOrCreateNodeText(observedNode);
            if (nodeText == null) throw new NullPointerException(observedNode.getClass().getSimpleName());
            LEXICAL_DIFFERENCE_CALCULATOR.calculatePropertyChange(nodeText, observedNode, property, oldValue, newValue);
        }

        private boolean isCompleteLine(List<TextElement> elements, int index) {
            if (index <= 0 || index >= elements.size()) return false;
            boolean complete = true;
            ListIterator<TextElement> iterator = elements.listIterator(index);
            while (iterator.hasNext()) {
                TextElement element = iterator.next();
                if (element.isNewline()) break;
                if (!element.isSpaceOrTab()) { complete = false; break; }
            }
            iterator = elements.listIterator(index);
            while (iterator.hasPrevious() && complete) {
                TextElement element = iterator.previous();
                if (element.isNewline()) break;
                if (!element.isSpaceOrTab()) complete = false;
            }
            return complete;
        }

        private void removeAllExtraCharacters(List<TextElement> elements, int index) {
            if (index < 0 || index >= elements.size()) return;
            removeAllExtraCharactersStartingFrom(elements.listIterator(index));
            removeAllExtraCharactersBeforePosition(elements.listIterator(index));
        }

        private void removeAllExtraCharactersBeforePosition(ListIterator<TextElement> iterator) {
            while (iterator.hasPrevious()) {
                TextElement element = iterator.previous();
                if (element.isSpaceOrTab()) iterator.remove(); else break;
            }
        }

        private void removeAllExtraCharactersStartingFrom(ListIterator<TextElement> iterator) {
            while (iterator.hasNext()) {
                TextElement element = iterator.next();
                if (element.isSpaceOrTab() || element.isNewline()) { iterator.remove(); if (element.isSpaceOrTab()) continue; }
                break;
            }
        }

        private TokenTextElement makeCommentToken(Comment comment) {
            if (comment.isJavadocComment()) return new TokenTextElement(JAVADOC_COMMENT, comment.getHeader() + comment.getContent() + comment.getFooter());
            if (comment.isLineComment()) return new TokenTextElement(SINGLE_LINE_COMMENT, comment.getHeader() + comment.getContent());
            if (comment.isBlockComment()) return new TokenTextElement(MULTI_LINE_COMMENT, comment.getHeader() + comment.getContent() + comment.getFooter());
            throw new UnsupportedOperationException("Unknown type of comment: " + comment.getClass().getSimpleName());
        }

        private int getIndexOfComment(Comment comment, NodeText nodeText) {
            List<TokenTextElement> tokens = findTokenTextElementForComment(comment, nodeText);
            if (!tokens.isEmpty()) return nodeText.findElement(tokens.get(0).and(tokens.get(0).matchByRange()));
            List<ChildTextElement> children = findChildTextElementForComment(comment, nodeText);
            return nodeText.findElement(children.get(0).and(children.get(0).matchByRange()));
        }

        private List<ChildTextElement> findChildTextElementForComment(Comment comment, NodeText nodeText) {
            List<ChildTextElement> result = selectMatchingChildElements(comment, nodeText);
            if (result.size() > 1) result = result.stream().filter(t -> isEqualRange(t.getChild().getRange(), comment.getRange())).collect(toList());
            if (result.size() != 1) throw new IllegalStateException("The matching child text element for the comment to be removed could not be found.");
            return result;
        }

        private List<ChildTextElement> selectMatchingChildElements(Comment comment, NodeText nodeText) {
            List<ChildTextElement> result = new ArrayList<>();
            for (TextElement element : nodeText.getElements()) if (element.isChild()) {
                ChildTextElement child = (ChildTextElement) element;
                if (child.isComment() && isSameComment((Comment) child.getChild(), comment)) result.add(child);
                else if (child.getChild().getComment().isPresent() && isSameComment(child.getChild().getComment().get(), comment)) result.add(child);
            }
            return result;
        }

        private boolean isSameComment(Comment first, Comment second) { return first.getContent().equals(second.getContent()); }

        private List<TokenTextElement> findTokenTextElementForComment(Comment comment, NodeText nodeText) {
            List<TokenTextElement> result;
            if (comment instanceof JavadocComment) result = nodeText.getElements().stream().filter(e -> e.isToken(JAVADOC_COMMENT)).map(e -> (TokenTextElement)e).filter(t -> t.getText().equals(comment.getHeader() + comment.getContent() + comment.getFooter())).collect(toList());
            else if (comment instanceof BlockComment) result = nodeText.getElements().stream().filter(e -> e.isToken(MULTI_LINE_COMMENT)).map(e -> (TokenTextElement)e).filter(t -> t.getText().equals(comment.getHeader() + comment.getContent() + comment.getFooter())).collect(toList());
            else result = nodeText.getElements().stream().filter(e -> e.isToken(SINGLE_LINE_COMMENT)).map(e -> (TokenTextElement)e).filter(t -> t.getText().trim().equals((comment.getHeader() + comment.getContent()).trim())).collect(toList());
            if (result.size() > 1) result = result.stream().filter(t -> isEqualRange(t.getToken().getRange(), comment.getRange())).collect(toList());
            return result;
        }

        private boolean isEqualRange(Optional<Range> first, Optional<Range> second) { return first.isPresent() && second.isPresent() && first.get().equals(second.get()); }

        private void fixIndentOfMovedNode(NodeText nodeText, int index) {
            if (index <= 0) return;
            TextElement current = null;
            for (int i = index - 1; i >= 0; i--) {
                TextElement candidate = nodeText.getTextElement(i);
                if (candidate.isSpaceOrTab()) current = candidate;
                if (!candidate.isSpaceOrTab()) {
                    if (candidate.isNewline() && i != index - 1) for (int j = 0; j < (index - 1) - i; j++) nodeText.addElement(index, new TokenTextElement(JavaToken.Kind.SPACE.getKind(), current == null ? " " : current.expand()));
                    break;
                }
            }
        }

        @Override
        public void concreteListChange(NodeList<?> list, ListChangeType type, int index, Node addedOrRemoved) {
            NodeText nodeText = getOrCreateNodeText(list.getParentNodeForChildren());
            List<DifferenceElement> elements;
            if (type == AstObserver.ListChangeType.REMOVAL) elements = LEXICAL_DIFFERENCE_CALCULATOR.calculateListRemovalDifference(findNodeListName(list), list, index);
            else if (type == AstObserver.ListChangeType.ADDITION) elements = LEXICAL_DIFFERENCE_CALCULATOR.calculateListAdditionDifference(findNodeListName(list), list, index, addedOrRemoved);
            else throw new UnsupportedOperationException();
            new Difference(elements, nodeText, list.getParentNodeForChildren()).apply();
        }

        @Override
        public void concreteListReplacement(NodeList<?> list, int index, Node oldValue, Node newValue) {
            NodeText nodeText = getOrCreateNodeText(list.getParentNodeForChildren());
            List<DifferenceElement> elements = LEXICAL_DIFFERENCE_CALCULATOR.calculateListReplacementDifference(findNodeListName(list), list, index, newValue);
            new Difference(elements, nodeText, list.getParentNodeForChildren()).apply();
        }
    }

    private static void storeInitialText(Node root) {
        Map<Node, List<JavaToken>> tokensByNode = new IdentityHashMap<>();
        root.getTokenRange().ifPresent(range -> {
            for (JavaToken token : range) {
                Range tokenRange = token.getRange().orElseThrow(() -> new RuntimeException("Token without range: " + token));
                Node owner = findNodeForToken(root, tokenRange).orElseThrow(() -> new RuntimeException("Token without node owning it: " + token));
                tokensByNode.computeIfAbsent(owner, n -> new LinkedList<>()).add(token);
            }
            new TreeVisitor() { @Override public void process(Node node) { if (!node.isPhantom()) storeInitialTextForOneNode(node, tokensByNode.get(node)); } }.visitBreadthFirst(root);
        });
    }

    private static Optional<Node> findNodeForToken(Node node, Range range) {
        if (node.isPhantom() || !node.hasRange() || !node.getRange().get().contains(range)) return Optional.empty();
        for (Node child : node.getChildNodes()) { Optional<Node> found = findNodeForToken(child, range); if (found.isPresent()) return found; }
        return Optional.of(node);
    }

    private static void storeInitialTextForOneNode(Node node, List<JavaToken> tokens) {
        if (tokens == null) tokens = Collections.emptyList();
        List<Pair<Range, TextElement>> elements = new LinkedList<>();
        for (Node child : node.getChildNodes()) if (!child.isPhantom()) {
            if (!child.hasRange()) throw new RuntimeException("Range not present on node " + child);
            elements.add(new Pair<>(child.getRange().get(), new ChildTextElement(child)));
        }
        for (JavaToken token : tokens) elements.add(new Pair<>(token.getRange().get(), new TokenTextElement(token)));
        elements.sort(comparing(e -> e.a.begin));
        node.setData(NODE_TEXT_DATA, new NodeText(elements.stream().map(p -> p.b).collect(toList())));
    }

    public static String print(Node node) {
        LexicalPreservingVisitor visitor = new LexicalPreservingVisitor();
        getOrCreateNodeText(node).getElements().forEach(element -> element.accept(visitor));
        return visitor.toString();
    }

    static NodeText getOrCreateNodeText(Node node) {
        if (!node.containsData(NODE_TEXT_DATA)) {
            NodeText nodeText = new NodeText();
            node.setData(NODE_TEXT_DATA, nodeText);
            LexicalPreservingPrinterTextHelper.prettyPrintingTextNode(node, nodeText, NODE_TEXT_DATA);
        }
        return node.getData(NODE_TEXT_DATA);
    }

    static List<TextElement> findIndentation(Node node) {
        return LexicalPreservingPrinterTextHelper.findIndentation(node, NODE_TEXT_DATA);
    }

    private static boolean isReturningOptionalNodeList(Method method) {
        if (!method.getReturnType().getCanonicalName().equals(JAVA_UTIL_OPTIONAL) || !(method.getGenericReturnType() instanceof ParameterizedType)) return false;
        ParameterizedType type = (ParameterizedType) method.getGenericReturnType();
        return type.getActualTypeArguments()[0].getTypeName().startsWith(JAVAPARSER_AST_NODELIST);
    }

    private static ObservableProperty findNodeListName(NodeList<?> nodeList) {
        Node parent = nodeList.getParentNodeForChildren();
        for (Method method : parent.getClass().getMethods()) {
            if (method.getParameterCount() != 0) continue;
            try {
                Object raw = method.invoke(parent);
                NodeList<?> result = raw instanceof Optional ? ((Optional<NodeList<?>>) raw).orElse(null) : (NodeList<?>) raw;
                if (result == nodeList) {
                    String name = method.getName();
                    if (name.startsWith("get")) name = name.substring(3);
                    return ObservableProperty.fromCamelCaseName(decapitalize(name));
                }
            } catch (IllegalAccessException | InvocationTargetException e) { throw new RuntimeException(e); }
        }
        throw new IllegalArgumentException("Cannot find list name of NodeList of size " + nodeList.size());
    }
}

package com.github.javaparser.printer.lexicalpreservation;

import static com.github.javaparser.GeneratedJavaParserConstants.BOOLEAN;
import static com.github.javaparser.GeneratedJavaParserConstants.BYTE;
import static com.github.javaparser.GeneratedJavaParserConstants.CHAR;
import static com.github.javaparser.GeneratedJavaParserConstants.DOUBLE;
import static com.github.javaparser.GeneratedJavaParserConstants.FLOAT;
import static com.github.javaparser.GeneratedJavaParserConstants.INT;
import static com.github.javaparser.GeneratedJavaParserConstants.JAVADOC_COMMENT;
import static com.github.javaparser.GeneratedJavaParserConstants.LBRACKET;
import static com.github.javaparser.GeneratedJavaParserConstants.LONG;
import static com.github.javaparser.GeneratedJavaParserConstants.MULTI_LINE_COMMENT;
import static com.github.javaparser.GeneratedJavaParserConstants.RBRACKET;
import static com.github.javaparser.GeneratedJavaParserConstants.SHORT;
import static com.github.javaparser.GeneratedJavaParserConstants.SINGLE_LINE_COMMENT;
import static com.github.javaparser.GeneratedJavaParserConstants.SPACE;

import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;

import com.github.javaparser.JavaToken;
import com.github.javaparser.ast.DataKey;
import com.github.javaparser.ast.Modifier;
import com.github.javaparser.ast.Node;
import com.github.javaparser.ast.body.VariableDeclarator;
import com.github.javaparser.ast.comments.BlockComment;
import com.github.javaparser.ast.comments.Comment;
import com.github.javaparser.ast.comments.JavadocComment;
import com.github.javaparser.ast.comments.LineComment;
import com.github.javaparser.ast.nodeTypes.NodeWithVariables;
import com.github.javaparser.ast.type.PrimitiveType;
import com.github.javaparser.printer.ConcreteSyntaxModel;
import com.github.javaparser.printer.concretesyntaxmodel.CsmElement;
import com.github.javaparser.printer.concretesyntaxmodel.CsmIndent;
import com.github.javaparser.printer.concretesyntaxmodel.CsmMix;
import com.github.javaparser.printer.concretesyntaxmodel.CsmToken;
import com.github.javaparser.printer.concretesyntaxmodel.CsmUnindent;
import com.github.javaparser.printer.lexicalpreservation.LexicalDifferenceCalculator.CsmChild;
import com.github.javaparser.utils.LineSeparator;

final class LexicalPreservingPrinterTextHelper {
    private LexicalPreservingPrinterTextHelper() {}

    static void prettyPrintingTextNode(Node node, NodeText nodeText, DataKey<NodeText> nodeTextData) {
        if (node instanceof PrimitiveType) {
            switch (((PrimitiveType) node).getType()) {
                case BOOLEAN: nodeText.addToken(BOOLEAN, node.toString()); break;
                case CHAR: nodeText.addToken(CHAR, node.toString()); break;
                case BYTE: nodeText.addToken(BYTE, node.toString()); break;
                case SHORT: nodeText.addToken(SHORT, node.toString()); break;
                case INT: nodeText.addToken(INT, node.toString()); break;
                case LONG: nodeText.addToken(LONG, node.toString()); break;
                case FLOAT: nodeText.addToken(FLOAT, node.toString()); break;
                case DOUBLE: nodeText.addToken(DOUBLE, node.toString()); break;
                default: throw new IllegalArgumentException();
            }
            return;
        }
        if (node instanceof JavadocComment) { Comment c = (Comment) node; nodeText.addToken(JAVADOC_COMMENT, c.getHeader() + c.getContent() + c.getFooter()); return; }
        if (node instanceof BlockComment) { Comment c = (Comment) node; nodeText.addToken(MULTI_LINE_COMMENT, c.getHeader() + c.getContent() + c.getFooter()); return; }
        if (node instanceof LineComment) { Comment c = (Comment) node; nodeText.addToken(SINGLE_LINE_COMMENT, c.getHeader() + c.getContent()); return; }
        if (node instanceof Modifier) { Modifier modifier = (Modifier) node; nodeText.addToken(LexicalDifferenceCalculator.toToken(modifier), modifier.getKeyword().asString()); return; }
        interpret(node, ConcreteSyntaxModel.forClass(node.getClass()), nodeText, nodeTextData);
    }

    private static NodeText interpret(Node node, CsmElement csm, NodeText nodeText, DataKey<NodeText> nodeTextData) {
        LexicalDifferenceCalculator.CalculatedSyntaxModel model = new LexicalDifferenceCalculator().calculatedSyntaxModelForNode(csm, node);
        List<TextElement> indentation = findIndentation(node, nodeTextData);
        boolean pendingIndentation = false;
        node.getComment().ifPresent(comment -> {
            if (!comment.hasRange()) {
                LineSeparator separator = node.getLineEndingStyleOrDefault(LineSeparator.SYSTEM);
                model.elements.add(0, new CsmToken(com.github.javaparser.TokenTypes.eolTokenKind(separator), separator.asRawString()));
                model.elements.add(0, new CsmChild(comment));
            }
        });
        for (CsmElement element : model.elements) {
            if (element instanceof CsmIndent) {
                int index = model.elements.indexOf(element);
                if (model.elements.size() > index && !(model.elements.get(index + 1) instanceof CsmUnindent)) for (int i = 0; i < Difference.STANDARD_INDENTATION_SIZE; i++) indentation.add(new TokenTextElement(SPACE, " "));
            } else if (element instanceof CsmUnindent) for (int i = 0; i < Difference.STANDARD_INDENTATION_SIZE && !indentation.isEmpty(); i++) indentation.remove(indentation.size() - 1);
            if (pendingIndentation && !(element instanceof CsmToken && ((CsmToken) element).isNewLine())) indentation.forEach(nodeText::addElement);
            pendingIndentation = false;
            if (element instanceof CsmChild) nodeText.addChild(((CsmChild) element).getChild());
            else if (element instanceof CsmToken) { CsmToken token = (CsmToken) element; nodeText.addToken(token.getTokenType(), token.getContent(node)); if (token.isNewLine()) pendingIndentation = true; }
            else if (element instanceof CsmMix) for (CsmElement child : ((CsmMix) element).getElements()) interpret(node, child, nodeText, nodeTextData);
            else if (!(element instanceof CsmIndent) && !(element instanceof CsmUnindent)) throw new UnsupportedOperationException(element.getClass().getSimpleName());
        }
        if (node instanceof VariableDeclarator) {
            VariableDeclarator variable = (VariableDeclarator) node;
            variable.getParentNode().ifPresent(parent -> ((NodeWithVariables<?>) parent).getMaximumCommonType().ifPresent(type -> {
                int extra = variable.getType().getArrayLevel() - type.getArrayLevel();
                for (int i = 0; i < extra; i++) { nodeText.addElement(new TokenTextElement(LBRACKET)); nodeText.addElement(new TokenTextElement(RBRACKET)); }
            }));
        }
        return nodeText;
    }

    static List<TextElement> findIndentation(Node node, DataKey<NodeText> nodeTextData) {
        List<TextElement> result = new LinkedList<>();
        Iterator<TokenTextElement> iterator = tokensPreceding(node, nodeTextData);
        while (iterator.hasNext()) {
            TokenTextElement element = iterator.next();
            if (element.getTokenKind() == SINGLE_LINE_COMMENT || element.isNewline()) break;
            result.add(element);
        }
        Collections.reverse(result);
        for (int i = 0; i < result.size(); i++) if (!result.get(i).isSpaceOrTab()) return result.subList(0, i);
        return result;
    }

    private static Iterator<TokenTextElement> tokensPreceding(Node node, DataKey<NodeText> nodeTextData) {
        if (!node.getParentNode().isPresent()) return new TextElementIteratorsFactory.EmptyIterator<>();
        Node parent = node.getParentNode().get();
        NodeText parentText = getOrCreateNodeText(parent, nodeTextData);
        int index = parentText.tryToFindChild(node);
        if (index == NodeText.NOT_FOUND) {
            if (parent instanceof VariableDeclarator) return tokensPreceding(parent, nodeTextData);
            return new TextElementIteratorsFactory.EmptyIterator<>();
        }
        return new TextElementIteratorsFactory.CascadingIterator<>(TextElementIteratorsFactory.partialReverseIterator(parentText, index - 1), () -> tokensPreceding(parent, nodeTextData));
    }

    private static NodeText getOrCreateNodeText(Node node, DataKey<NodeText> nodeTextData) {
        if (!node.containsData(nodeTextData)) {
            NodeText text = new NodeText();
            node.setData(nodeTextData, text);
            prettyPrintingTextNode(node, text, nodeTextData);
        }
        return node.getData(nodeTextData);
    }
}

